/**
 * fhirEnrollmentToRules(bundle, options)
 * Flattens a FHIR R4 enrollment "transaction" Bundle (Patient + Coverage)
 * into a flat JSON payload for a rules engine. One record per covered member.
 *   bundle  : FHIR Bundle object OR JSON string
 *   options : { asOf: 'YYYY-MM-DD' }  reference date for age (default: today)
 * ES5-safe (Goja). Single function, nothing to import.
 */
function fhirEnrollmentToRules(bundle, options) {
  "use strict"

  var COUPE_SYSTEM = "https://coupehealth.com/fhir/identifier/coupe"
  var PARTNER_SYSTEM = "https://coupehealth.com/fhir/identifier/partner"
  var LEGACY_SYSTEM = "https://coupehealth.com/fhir/identifier/legacy"
  var SSN_SYSTEM = "http://hl7.org/fhir/sid/us-ssn"

  options = options || {}
  if (typeof bundle === "string") bundle = JSON.parse(bundle)
  if (!bundle || bundle.resourceType !== "Bundle") {
    throw new Error("Input is not a FHIR Bundle")
  }
  var asOf = options.asOf || null
  var entries = bundle.entry && bundle.entry.length ? bundle.entry : []

  function safeArray(a) {
    return a && a.length ? a : []
  }

  function findIdentifier(identifiers, opts) {
    identifiers = safeArray(identifiers)
    opts = opts || {}
    for (var i = 0; i < identifiers.length; i++) {
      var id = identifiers[i]
      if (!id) continue
      if (opts.system && id.system === opts.system) return id.value || null
      if (opts.typeCode && id.type && id.type.coding) {
        for (var j = 0; j < id.type.coding.length; j++) {
          if (id.type.coding[j].code === opts.typeCode) return id.value || null
        }
      }
    }
    return null
  }

  function parseName(patient) {
    var names = safeArray(patient.name)
    if (!names.length) return { given: "", family: "", full: "" }
    var n = names[0]
    var given = n.given && n.given.length ? n.given.join(" ") : ""
    var family = n.family || ""
    return {
      given: given,
      family: family,
      full: (given + " " + family)
        .replace(/\s+/g, " ")
        .replace(/^\s+|\s+$/g, ""),
    }
  }

  function calcAge(birthDate, ref) {
    if (!birthDate) return null
    var b = new Date(birthDate)
    if (isNaN(b.getTime())) return null
    var r = ref ? new Date(ref) : new Date()
    var age = r.getFullYear() - b.getFullYear()
    var md = r.getMonth() - b.getMonth()
    if (md < 0 || (md === 0 && r.getDate() < b.getDate())) age--
    return age
  }

  function coverageClass(coverage, code) {
    var classes = safeArray(coverage["class"])
    for (var i = 0; i < classes.length; i++) {
      var c = classes[i]
      if (c.type && c.type.coding) {
        for (var j = 0; j < c.type.coding.length; j++) {
          if (c.type.coding[j].code === code)
            return { value: c.value || null, name: c.name || null }
        }
      }
    }
    return null
  }

  function refIdValue(ref, system) {
    if (ref && ref.identifier && ref.identifier.value) {
      if (!system || ref.identifier.system === system)
        return ref.identifier.value
    }
    return null
  }

  function firstCoding(cc) {
    if (cc && cc.coding && cc.coding.length) {
      return {
        code: cc.coding[0].code || null,
        display: cc.coding[0].display || null,
      }
    }
    return { code: null, display: null }
  }

  function coupeFromUrl(url) {
    if (!url) return null
    var m = /coupe\|([^&\s]+)/.exec(url)
    return m ? m[1] : null
  }

  // index Patient entries by fullUrl
  var patientIndex = {}
  var allPatientUrls = []
  for (var p = 0; p < entries.length; p++) {
    var pe = entries[p]
    if (pe && pe.resource && pe.resource.resourceType === "Patient") {
      if (pe.fullUrl) patientIndex[pe.fullUrl] = pe
      allPatientUrls.push(pe.fullUrl)
    }
  }

  // build one member per Coverage
  var members = []
  var coveredUrls = {}
  var subscriberCoupeId = null

  for (var c2 = 0; c2 < entries.length; c2++) {
    var ce = entries[c2]
    if (!ce || !ce.resource || ce.resource.resourceType !== "Coverage") continue
    var cov = ce.resource

    var beneRef = (cov.beneficiary && cov.beneficiary.reference) || null
    if (beneRef) coveredUrls[beneRef] = true
    var patEntry = beneRef ? patientIndex[beneRef] : null
    var pat = (patEntry && patEntry.resource) || {}

    var name = parseName(pat)
    var coupeId =
      refIdValue(cov.beneficiary, COUPE_SYSTEM) ||
      (patEntry ? coupeFromUrl(patEntry.request && patEntry.request.url) : null)
    var rel = firstCoding(cov.relationship)
    var covType = firstCoding(cov.type)
    var grp = coverageClass(cov, "group")
    var plan = coverageClass(cov, "plan")
    var age = calcAge(pat.birthDate || null, asOf)
    var mbrNo = findIdentifier(cov.identifier, {
      system: COUPE_SYSTEM,
      typeCode: "MB",
    })

    var member = {
      coupeId: coupeId,
      memberNumber: mbrNo,
      partnerMemberId: findIdentifier(pat.identifier, {
        system: PARTNER_SYSTEM,
      }),
      ssn: findIdentifier(pat.identifier, {
        system: SSN_SYSTEM,
        typeCode: "SS",
      }),

      firstName: name.given,
      lastName: name.family,
      fullName: name.full,
      gender: pat.gender || null,
      birthDate: pat.birthDate || null,
      age: age,
      isMinor: age !== null ? age < 18 : null,

      relationship: rel.code,
      isSubscriber: rel.code === "self",
      dependentNumber: cov.dependent || null,
      subscriberCoupeId: refIdValue(cov.subscriber, COUPE_SYSTEM),

      coverage: {
        status: cov.status || null,
        active: cov.status === "active",
        memberNumber: mbrNo,
        typeCode: covType.code,
        typeDisplay: covType.display,
        startDate: cov.period ? cov.period.start || null : null,
        endDate: cov.period ? cov.period.end || null : null,
        groupId: grp ? grp.value : null,
        groupName: grp ? grp.name : null,
        plan: plan ? plan.value : null,
        planName: plan ? plan.name : null,
        network: cov.network || null,
        policyHolder: (cov.policyHolder && cov.policyHolder.display) || null,
        policyHolderId: cov.policyHolder
          ? findIdentifier([cov.policyHolder.identifier], {
              system: LEGACY_SYSTEM,
            })
          : null,
        payor: (cov.payor && cov.payor.length && cov.payor[0].display) || null,
        payorId:
          cov.payor && cov.payor.length
            ? refIdValue(cov.payor[0], COUPE_SYSTEM)
            : null,
      },
    }

    if (member.isSubscriber && member.coupeId)
      subscriberCoupeId = member.coupeId
    members.push(member)
  }

  // patients with no coverage (flagged, not dropped)
  var patientsWithoutCoverage = []
  for (var u = 0; u < allPatientUrls.length; u++) {
    var url = allPatientUrls[u]
    if (!coveredUrls[url]) {
      var orphan = patientIndex[url]
      patientsWithoutCoverage.push({
        coupeId: coupeFromUrl(orphan.request && orphan.request.url),
        fullName: parseName(orphan.resource).full,
      })
    }
  }

  // subscriber first, then by dependent number
  members.sort(function (a, b) {
    if (a.isSubscriber && !b.isSubscriber) return -1
    if (!a.isSubscriber && b.isSubscriber) return 1
    var da = a.dependentNumber || "99"
    var db = b.dependentNumber || "99"
    return da < db ? -1 : da > db ? 1 : 0
  })

  var result = {
    bundleId: bundle.id || null,
    bundleType: bundle.type || null,
    enrollmentType: members.length > 1 ? "family" : "single",
    ageAsOf: asOf || new Date().toISOString().slice(0, 10),
    subscriberCoupeId: subscriberCoupeId,
    memberCount: members.length,
    members: members,
  }
  if (patientsWithoutCoverage.length)
    result.patientsWithoutCoverage = patientsWithoutCoverage
  return result
}
let final = {}
final["a"] = fhirEnrollmentToRules({{.Trigger.input_att1}})
final["b"] = fhirEnrollmentToRules({{.Trigger.input_att2}})
final;
